  function renderAttributionHistory(history){if(!history?.trackedTouchCount)return '';const words=ar?{title:'سجل مصدر الحملة',first:'أول مصدر مسجل',latest:'أحدث مصدر مسجل',both:'المصدر الأول والأحدث',reference:'الطلب',date:'تاريخ الإرسال',source:'المصدر',medium:'الوسيط',campaign:'الحملة',content:'المحتوى',term:'مصطلح البحث',landing:'صفحة الوصول',referrer:'مصدر الإحالة'}:{title:'Campaign attribution history',first:'First recorded touch',latest:'Latest recorded touch',both:'First and latest recorded touch',reference:'Application',date:'Submitted',source:'Source',medium:'Medium',campaign:'Campaign',content:'Content',term:'Search term',landing:'Landing page',referrer:'Referrer'};const names={utmSource:words.source,utmMedium:words.medium,utmCampaign:words.campaign,utmContent:words.content,utmTerm:words.term,landingPage:words.landing,referrer:words.referrer};const renderTouch=(title,touch)=>`<article class="attribution-touch"><strong>${escape(title)}</strong><small>${escape(words.reference)} ${escape(touch.referenceCode||'—')} · ${escape(words.date)} ${escape(date(touch.submittedAt))}</small><dl>${Object.entries(touch.attribution||{}).map(([key,value])=>`<div><dt>${escape(names[key]||key)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl></article>`;const first=history.firstTouch,latest=history.latestTouch,same=first&&latest&&first.submissionId===latest.submissionId;return `<section class="campaign-attribution-history"><div class="section-title">${escape(words.title)} · ${Number(history.trackedTouchCount)}</div><div class="attribution-touch-grid">${same?renderTouch(words.both,first):`${first?renderTouch(words.first,first):''}${latest?renderTouch(words.latest,latest):''}`}</div></section>`;}
